import zeros = require( '@stdlib/ndarray/base/zeros' );
import Slice = require( '@stdlib/slice/ctor' );
import MultiSlice = require( '@stdlib/slice/multi' );
import fillSlice = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	var s0 = new Slice( 0, 2 );
	var s1 = new Slice( 2, 3 );
	var s = new MultiSlice( s0, s1 );

	fillSlice( zeros( 'float64', [ 2, 4 ], 'row-major' ), s, 10.0 ); // $ExpectType float64ndarray
	fillSlice( zeros( 'complex128', [ 2, 4 ], 'row-major' ), s, 10.0 ); // $ExpectType complex128ndarray
	fillSlice( zeros( 'complex128', [ 2, 4 ], 'row-major' ), s, { 're': 10.0, 'im': 10.0 } ); // $ExpectType complex128ndarray

	fillSlice( zeros( 'generic', [ 2, 4 ], 'row-major' ), s, 10.0 ); // $ExpectType genericndarray<number>
	fillSlice<number | string>( zeros( 'generic', [ 2, 4 ], 'row-major' ), s, 'beep' ); // $ExpectType genericndarray<string | number>
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray-like object...
{
	var s0 = new Slice( 0, 2 );
	var s1 = new Slice( 2, 3 );
	var s = new MultiSlice( s0, s1 );

	fillSlice( '5', s, 10.0 ); // $ExpectError
	fillSlice( 5, s, 10.0 ); // $ExpectError
	fillSlice( true, s, 10.0 ); // $ExpectError
	fillSlice( false, s, 10.0 ); // $ExpectError
	fillSlice( null, s, 10.0 ); // $ExpectError
	fillSlice( undefined, s, 10.0 ); // $ExpectError
	fillSlice( {}, s, 10.0 ); // $ExpectError
	fillSlice( [ 1 ], s, 10.0 ); // $ExpectError
	fillSlice( ( x: number ): number => x, s, 10.0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a MultiSLice instance...
{
	const x = zeros( 'float64', [ 2, 2 ], 'row-major' );

	fillSlice( x, '5', 10.0 ); // $ExpectError
	fillSlice( x, 5, 10.0 ); // $ExpectError
	fillSlice( x, true, 10.0 ); // $ExpectError
	fillSlice( x, false, 10.0 ); // $ExpectError
	fillSlice( x, null, 10.0 ); // $ExpectError
	fillSlice( x, undefined, 10.0 ); // $ExpectError
	fillSlice( x, {}, 10.0 ); // $ExpectError
	fillSlice( x, [ 1 ], 10.0 ); // $ExpectError
	fillSlice( x, ( x: number ): number => x, 10.0 ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( 'float64', [ 2, 4 ], 'row-major' );
	var s0 = new Slice( 0, 2 );
	var s1 = new Slice( 2, 3 );
	var s = new MultiSlice( s0, s1 );

	fillSlice(); // $ExpectError
	fillSlice( x, s, 10.0, {} ); // $ExpectError
}
